using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEditor;using UnityEngine;using UnityEngine.Rendering;
namespace ParkingLotEnvironment.CloudPilot {public static class PorterFinalBinding {
 [Serializable]class Record{public string name,file;public int vertexCount,indexCount,material;}
 [Serializable]class Model{public Record[] meshes;}
 public static void Apply(GameObject root){string w=ContextBuilder.W;Directory.CreateDirectory(w+"/PorterFinal");AssetDatabase.Refresh();var data=JsonUtility.FromJson<Model>(File.ReadAllText(w+"/PorterData/porter.json"));var meshes=new Dictionary<string,Mesh>();foreach(var item in data.meshes){var mesh=new Mesh{name="PorterFinal_"+item.name,indexFormat=IndexFormat.UInt32};var vv=new Vector3[item.vertexCount];var nn=new Vector3[item.vertexCount];var uv=new Vector2[item.vertexCount];var indices=new int[item.indexCount];using(var r=new BinaryReader(File.OpenRead(w+"/PorterData/"+item.file))){for(int i=0;i<vv.Length;i++){vv[i]=new Vector3(r.ReadSingle(),r.ReadSingle(),r.ReadSingle());nn[i]=new Vector3(r.ReadSingle(),r.ReadSingle(),r.ReadSingle());uv[i]=new Vector2(r.ReadSingle(),r.ReadSingle());}for(int i=0;i<indices.Length;i++)indices[i]=(int)r.ReadUInt32();}mesh.vertices=vv;mesh.normals=nn;mesh.uv=uv;mesh.triangles=indices;mesh.RecalculateBounds();mesh.RecalculateTangents();AssetDatabase.CreateAsset(mesh,w+"/PorterFinal/"+mesh.name+".asset");meshes[item.name]=mesh;}
  var car=root.GetComponentInChildren<ParkingLotEnvironment.Training.ParkingTrainingLayout>().transform.Find("Parked_T_4_PortedModel");Bind(car.gameObject,meshes);var glass=AssetDatabase.LoadAssetAtPath<Material>(w+"/Porter_Glass.mat");glass.shader=Shader.Find("Standard");glass.shaderKeywords=new string[0];glass.color=new Color(.018f,.028f,.039f,1);glass.SetFloat("_Metallic",.05f);glass.SetFloat("_Glossiness",.94f);glass.SetFloat("_Mode",0);glass.SetInt("_SrcBlend",1);glass.SetInt("_DstBlend",0);glass.SetInt("_ZWrite",1);glass.SetOverrideTag("RenderType","Opaque");glass.renderQueue=-1;EditorUtility.SetDirty(glass);var prefab=PrefabUtility.LoadPrefabContents(w+"/HyundaiPorterII_Blue.prefab");try{Bind(prefab,meshes);PrefabUtility.SaveAsPrefabAsset(prefab,w+"/HyundaiPorterII_Blue.prefab");}finally{PrefabUtility.UnloadPrefabContents(prefab);}var layout=root.GetComponentInChildren<ParkingLotEnvironment.Training.ParkingTrainingLayout>();foreach(var obstacle in layout.obstacles.Where(o=>o.category=="SUV")){var r=layout.transform.Find(obstacle.id).Find("AttachedRearPlate");if(r)r.position=new Vector3(r.position.x,.82f,r.position.z);}AssetDatabase.SaveAssets();
 }
 static void Bind(GameObject g,Dictionary<string,Mesh> meshes){foreach(var f in g.GetComponentsInChildren<MeshFilter>())if(meshes.TryGetValue(f.name,out var m)){f.sharedMesh=m;EditorUtility.SetDirty(f);}}
}}
